import{_ as t,o as i,c as n,a3 as r}from"./chunks/framework.B5WAEDB7.js";const p=JSON.parse('{"title":"Zeiterfassung einrichten","description":"Kommen, Pause und Gehen in der App – die Zeiten liegen in einem Grid, auf das die Belegschaft keinen Zugriff braucht.","frontmatter":{"title":"Zeiterfassung einrichten","description":"Kommen, Pause und Gehen in der App – die Zeiten liegen in einem Grid, auf das die Belegschaft keinen Zugriff braucht."},"headers":[],"relativePath":"apptiveteams/zeiterfassung.md","filePath":"apptiveteams/zeiterfassung.md","lastUpdated":1788793624000}'),d={name:"apptiveteams/zeiterfassung.md"};function a(s,e,l,o,c,h){return i(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="zeiterfassung-einrichten" tabindex="-1">Zeiterfassung einrichten <a class="header-anchor" href="#zeiterfassung-einrichten" aria-label="Permalink to &quot;Zeiterfassung einrichten&quot;">​</a></h1><p>Ein Tab vom Typ <code>TimeTracking</code> bringt eine Zeiterfassung in die App: <strong>Kommen</strong>, <strong>Pause</strong> und <strong>Gehen</strong> per Knopfdruck, manuelle Einträge über ein Formular, eine Liste für heute und eine Wochenübersicht. Jede erfasste Zeit ist eine Zeile in einem Grid Ihres ApptiveGrid-Kontos.</p><p>Die Belegschaft braucht dafür <strong>keinen Zugriff auf den Space</strong> mit den Zeiten. Die App arbeitet ausschließlich über geteilte Links: eine Ansicht zum Lesen, ein Formular zum Anlegen und einen Bearbeitungslink pro Zeile zum Ändern. So sieht jede Person nur ihre eigenen Zeiten, und Sie behalten die Auswertung im Grid.</p><h2 id="was-sie-brauchen" tabindex="-1">Was Sie brauchen <a class="header-anchor" href="#was-sie-brauchen" aria-label="Permalink to &quot;Was Sie brauchen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Baustein</th><th>Wo</th><th>Zweck</th></tr></thead><tbody><tr><td>Grid mit den Zeiteinträgen</td><td>Zeiterfassungs-Space</td><td>Speichert die Zeiten</td></tr><tr><td>Formular auf dem Grid</td><td>Zeiterfassungs-Space</td><td>Legt Einträge an, dient auch zum Ändern</td></tr><tr><td>Gefilterte, geteilte Ansicht</td><td>Zeiterfassungs-Space</td><td>Liefert der App die eigenen Einträge</td></tr><tr><td>Flow „Bearbeitungslink erzeugen“</td><td>Zeiterfassungs-Space</td><td>Macht Pause und Gehen möglich</td></tr><tr><td>Tabs-Zeile vom Typ <code>TimeTracking</code></td><td>Team Space</td><td>Zeigt den Tab in der App</td></tr></tbody></table><p>Der Zeiterfassungs-Space kann ein eigener Space sein, den nur Sie sehen. Das ist der empfohlene Weg.</p><h2 id="_1-das-grid" tabindex="-1">1. Das Grid <a class="header-anchor" href="#_1-das-grid" aria-label="Permalink to &quot;1. Das Grid&quot;">​</a></h2><p>Legen Sie ein Grid mit diesen Feldern an. Die Namen sind frei, die <strong>Keys</strong> müssen genau stimmen. → <a href="/apptiveteams/team-space#keys-wie-die-app-ihre-grids-findet">Keys vergeben</a></p><table tabindex="0"><thead><tr><th>Feld-Key</th><th>Feldtyp</th><th>Pflicht</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>start</code></td><td>Datum und Uhrzeit</td><td>ja</td><td>Beginn der Arbeitszeit</td></tr><tr><td><code>end</code></td><td>Datum und Uhrzeit</td><td>ja</td><td>Ende der Arbeitszeit; leer, solange sie läuft</td></tr><tr><td><code>breakMinutes</code></td><td>Zahl</td><td>ja</td><td>Summe der Pausen in Minuten</td></tr><tr><td><code>breakStart</code></td><td>Datum und Uhrzeit</td><td>ja</td><td>Beginn einer laufenden Pause; sonst leer</td></tr><tr><td><code>editLink</code></td><td>Weblink</td><td>ja</td><td>Bearbeitungslink der Zeile, den der Flow einträgt</td></tr><tr><td><code>note</code></td><td>Text</td><td>nein</td><td>Notiz, zum Beispiel „Kundentermin“</td></tr><tr><td><code>createdBy</code></td><td>Erstellt von</td><td>ja</td><td>Wird automatisch gesetzt; darüber filtert die Ansicht</td></tr></tbody></table><p>Weitere Felder wie Projekt oder Anhänge dürfen im Grid stehen, die App lässt sie unangetastet.</p><div class="tip custom-block"><p class="custom-block-title">Netto-Stunden im Grid</p><p>Eine Formel-Spalte wie <code>(end - start) - breakMinutes</code> liefert die Netto-Arbeitszeit direkt im Grid – für Auswertungen und Exporte, ohne die App zu berühren.</p></div><h2 id="_2-das-formular" tabindex="-1">2. Das Formular <a class="header-anchor" href="#_2-das-formular" aria-label="Permalink to &quot;2. Das Formular&quot;">​</a></h2><p>Erstellen Sie ein Formular auf dem Grid mit den Feldern <code>start</code>, <code>end</code>, <code>breakMinutes</code>, <code>breakStart</code> und optional <code>note</code>. Teilen Sie es mit der Beschränkung <strong>Jeder registrierte Benutzer</strong>: So wird bei jedem Eintrag die angemeldete Person als „Erstellt von“ eingetragen.</p><p>Dasselbe Formular verwendet der Flow im nächsten Schritt für die Bearbeitungslinks. → <a href="/formulare/formular-teilen">Formular teilen</a></p><h2 id="_3-die-ansicht" tabindex="-1">3. Die Ansicht <a class="header-anchor" href="#_3-die-ansicht" aria-label="Permalink to &quot;3. Die Ansicht&quot;">​</a></h2><p>Legen Sie eine Ansicht auf dem Grid an, filtern Sie auf <strong>Erstellt von ist die angemeldete Person</strong> und blenden Sie alle Felder aus Schritt 1 ein. Teilen Sie die Ansicht per Link, ebenfalls nur für angemeldete Personen. → <a href="/ansichten/ansicht-teilen">Ansicht teilen</a></p><p>Der Filter wird auf dem Server ausgewertet. Jede Person bekommt über denselben Link nur ihre eigenen Zeilen.</p><h2 id="_4-der-flow" tabindex="-1">4. Der Flow <a class="header-anchor" href="#_4-der-flow" aria-label="Permalink to &quot;4. Der Flow&quot;">​</a></h2><p>Ohne Bearbeitungslink kann die App eine Zeile nicht ändern, Pause und Gehen bleiben gesperrt. Ein Flow erzeugt den Link automatisch:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Auslöser: Eintrag erstellt              (Grid aus Schritt 1)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Vorausgefüllter Formularlink            (Formular aus Schritt 2)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Eintrag ändern                          → Feld editLink = erzeugter Link</span></span></code></pre></div><p>Aktivieren Sie den Flow. Nach Kommen zeigt die App „Wird mit ApptiveGrid synchronisiert …“, bis der Link in der Zeile steht, in der Regel wenige Sekunden. → <a href="/formulare/eintraege-bearbeiten">Einträge per Formular bearbeiten</a></p><div class="warning custom-block"><p class="custom-block-title">Flow vergessen ist der häufigste Fehler</p><p>Bleibt die App nach Kommen dauerhaft beim Synchronisieren, ist der Flow nicht aktiv oder schreibt in ein anderes Feld. Prüfen Sie in der Zeile, ob <code>editLink</code> gefüllt ist.</p></div><h2 id="_5-die-tabs-zeile" tabindex="-1">5. Die Tabs-Zeile <a class="header-anchor" href="#_5-die-tabs-zeile" aria-label="Permalink to &quot;5. Die Tabs-Zeile&quot;">​</a></h2><p>Im Team Space ergänzen Sie im Grid <code>tabs</code> eine Zeile:</p><table tabindex="0"><thead><tr><th>Feld-Key</th><th>Wert</th></tr></thead><tbody><tr><td><code>title</code></td><td>zum Beispiel „Zeiten“</td></tr><tr><td><code>icon</code></td><td>einfarbiges SVG</td></tr><tr><td><code>type</code></td><td><code>TimeTracking</code></td></tr><tr><td><code>uri</code></td><td>der Link der geteilten Ansicht</td></tr><tr><td><code>formUri</code></td><td>der Link des Formulars</td></tr></tbody></table><p><code>formUri</code> ist ein neues Weblink-Feld im Tabs-Grid. Legen Sie es an, falls es noch fehlt, und ergänzen Sie <code>TimeTracking</code> in der Einzelauswahl von <code>type</code>. → <a href="/apptiveteams/tabs">Tabs einrichten</a></p><div class="tip custom-block"><p class="custom-block-title">Zeiten im Team Space</p><p>Liegen die Zeiten im Team Space selbst und dürfen die Mitglieder das Grid sehen, können Sie statt <code>uri</code> das Feld <code>gridUri</code> auf Grid oder Ansicht zeigen lassen. <code>formUri</code> bleibt nötig. Sind beide gesetzt, gilt <code>gridUri</code>.</p></div><h2 id="so-arbeitet-die-app" tabindex="-1">So arbeitet die App <a class="header-anchor" href="#so-arbeitet-die-app" aria-label="Permalink to &quot;So arbeitet die App&quot;">​</a></h2><ul><li><strong>Kommen</strong> legt sofort eine Zeile ohne Ende an. Der Timer läuft auf allen Geräten der Person weiter, auch nach einem Neustart der App.</li><li><strong>Pause</strong> merkt sich den Beginn in <code>breakStart</code>; <strong>Pause beenden</strong> rechnet die Minuten auf <code>breakMinutes</code>. Pausen werden auf ganze Minuten gerundet.</li><li><strong>Gehen</strong> setzt das Ende. Netto-Zeit ist Ende minus Start minus Pausen.</li><li><strong>Manuelle Einträge</strong> über den Plus-Button dürfen an jedem Datum liegen. Bearbeiten ist nur für Einträge des heutigen Tages möglich; Löschen gibt es in der App nicht, Korrekturen machen Sie im Grid.</li><li>Nach sechs Stunden ohne Pause erinnert ein Hinweis an die Pause.</li><li>Die App zeigt die Texte in der Sprache des Geräts (Deutsch oder Englisch) und verwendet die Primärfarbe des Team Space.</li></ul><h2 id="wenn-etwas-fehlt" tabindex="-1">Wenn etwas fehlt <a class="header-anchor" href="#wenn-etwas-fehlt" aria-label="Permalink to &quot;Wenn etwas fehlt&quot;">​</a></h2><p>Die App nennt fehlende Feld-Keys direkt im Tab, zusammen mit den Feldern, die die Ansicht oder das Formular tatsächlich liefern. Fehlt zum Beispiel <code>breakStart</code> im Formular, erscheint das nach dem ersten Kommen als Meldung.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Ursache</th></tr></thead><tbody><tr><td>Kein Tab in der App</td><td>Tabs-Zeile unvollständig: <code>type</code>, <code>uri</code> oder <code>formUri</code> fehlt, oder das Icon ist kein SVG</td></tr><tr><td>„Fehlende Feld-Keys: …“ beim Öffnen</td><td>Feld fehlt in der Ansicht oder hat keinen Key</td></tr><tr><td>„Speichern fehlgeschlagen“ mit fehlenden Keys nach Kommen</td><td>Feld fehlt im Formular</td></tr><tr><td>Dauerhaft „Wird mit ApptiveGrid synchronisiert …“</td><td>Flow nicht aktiv oder <code>editLink</code> nicht in der Ansicht sichtbar</td></tr><tr><td>Eine andere Person sieht fremde Zeiten</td><td>Ansicht ist nicht auf „Erstellt von ist angemeldete Person“ gefiltert</td></tr></tbody></table><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/apptiveteams/tabs">Tabs einrichten</a></li><li><a href="/formulare/eintraege-bearbeiten">Einträge per Formular bearbeiten</a></li><li><a href="/ansichten/ansicht-teilen">Ansicht teilen</a></li><li><a href="/apptiveteams/fehlerbehebung">Tipps und Fehlerbehebung</a></li></ul>`,34)])])}const m=t(d,[["render",a]]);export{p as __pageData,m as default};
